      "①【锦官城方向反推错】锦官城节点 exits 写的是 e:鱼定村，但鱼定村去锦官城是 sw:锦官城——去程西南、回程却标正东，方向不互逆。坐标验证：锦官城(-2,1) vs 鱼定村(0,0)，从锦官城看鱼定村 Δx+2 Δy-1 = 东北(ne)。九宫格直接读 room.exits 画方向，故鱼定村被画在东格。修复：锦官城 exits 改 e→ne。（另用脚本审计全图出口对称性，顺带发现山洞↔顶峰也有同类方向bug——山洞写n→顶峰但几何是正东、且与顶峰w不互逆——作者指示本轮只修锦官城，山洞顶峰下轮处理。）",
      "②【外层移动被内层判定截胡】根因：autoTravelTo(已探索据点走自动寻路)内部发的是 act(first) 和队列 act(cmd)，全都没带 forceLayer。而内层判定条件(2713)是 forceLayer!==\"outer\" 即触发——当玩家此刻正站在某内层房间(innerRoomName有值)时，autoTravelTo 发出的 act(\"西\") 因无 forceLayer 被内层判定截胡，表现为\"外层点方向去已探索据点却变成内层移动\"。\"有时\"取决于目标是否已探索：未探索走 act(..,{forceLayer:outer}) 正常，已探索走 autoTravelTo 无标记就串内层。修复：autoTravelTo 首步与队列后续步都带 opts:{forceLayer:\"outer\"}(队列消费处4649已透传opts)。确认防连点(300ms)不误杀队列步——队列步要等loading变false(上一步AI完成、数秒)才出队，间隔远超300ms。",
